local ProofingBasketMaker = {}
local PRODUCTS = {
    iron_proofingbasket = { name = "Železni vzhodna košara", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vzhodna košara za pekarno." },
    bronze_proofingbasket = { name = "Bronast vzhodna košara", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vzhodna košara za pekarno." },
    silver_proofingbasket = { name = "Srebrn vzhodna košara", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vzhodna košara za pekarno." },
    gilded_proofingbasket = { name = "Pozlačen vzhodna košara", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vzhodna košara za pekarno." },
    jewel_set_proofingbasket = { name = "Draguljast vzhodna košara", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vzhodna košara za pekarno." },
    royal_sovereign_proofingbasket = { name = "Kraljevski suveren vzhodna košara", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vzhodna košara z biseri za krono." },
}
local BUILDINGS = {
    proofingbasket_workshop = { name = "Proofingbasket delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    proofingbasket_house = { name = "Proofingbasket hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_proofingbasket_atelier = { name = "Mojstrski proofingbasket atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_proofingbasket_palace = { name = "Suverena proofingbasket palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ProofingBasketMaker.ironStock = 10; ProofingBasketMaker.bronzeStock = 8; ProofingBasketMaker.woodStock = 20; ProofingBasketMaker.leatherStock = 12; ProofingBasketMaker.silverStock = 8; ProofingBasketMaker.goldStock = 6; ProofingBasketMaker.jewelStock = 4; ProofingBasketMaker.pearlStock = 4
ProofingBasketMaker.productStock = {}; ProofingBasketMaker.buildings = {}; ProofingBasketMaker.maker = nil; ProofingBasketMaker.activeMaking = {}; ProofingBasketMaker.totalProducts = 0; ProofingBasketMaker.dayTimer = 0
function ProofingBasketMaker.init() ProofingBasketMaker.ironStock=10; ProofingBasketMaker.bronzeStock=8; ProofingBasketMaker.woodStock=20; ProofingBasketMaker.leatherStock=12; ProofingBasketMaker.silverStock=8; ProofingBasketMaker.goldStock=6; ProofingBasketMaker.jewelStock=4; ProofingBasketMaker.pearlStock=4; ProofingBasketMaker.productStock={}; ProofingBasketMaker.buildings={}; ProofingBasketMaker.maker=nil; ProofingBasketMaker.activeMaking={}; ProofingBasketMaker.totalProducts=0; ProofingBasketMaker.dayTimer=0; print("[ProofingBasketMaker] Royal Proofing Basket Maker System initialized (6 products, 4 buildings)") end
function ProofingBasketMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ProofingBasketMaker.maker={name=n or ("Košar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Košar najet: %s (spretnost: %d)",ProofingBasketMaker.maker.name,s),"success") end; return true end
function ProofingBasketMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ProofingBasketMaker.build(id) local ok,e=ProofingBasketMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ProofingBasketMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ProofingBasketMaker.getQualityBonus() local b=0; for _,bd in ipairs(ProofingBasketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ProofingBasketMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ProofingBasketMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ProofingBasketMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ProofingBasketMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ProofingBasketMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ProofingBasketMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ProofingBasketMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ProofingBasketMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ProofingBasketMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ProofingBasketMaker.buildings==0 then return false,"Potrebna košarska delavnica" end; if not ProofingBasketMaker.maker then return false,"Potreben kosar" end; return true end
function ProofingBasketMaker.make(pt,qty) qty=qty or 1; local ok,e=ProofingBasketMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ProofingBasketMaker.ironStock=ProofingBasketMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ProofingBasketMaker.bronzeStock=ProofingBasketMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ProofingBasketMaker.woodStock=ProofingBasketMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ProofingBasketMaker.leatherStock=ProofingBasketMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ProofingBasketMaker.silverStock=ProofingBasketMaker.silverStock-d.silverCost*qty end; if d.goldCost then ProofingBasketMaker.goldStock=ProofingBasketMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ProofingBasketMaker.jewelStock=ProofingBasketMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ProofingBasketMaker.pearlStock=ProofingBasketMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ProofingBasketMaker.maker then t=math.max(1,t-math.floor(ProofingBasketMaker.maker.skill/13)) end; table.insert(ProofingBasketMaker.activeMaking,{id="proofingbasket_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ProofingBasketMaker.completeMaking(m) local q=1.0+(ProofingBasketMaker.getQualityBonus()/100); if ProofingBasketMaker.maker then q=q+(ProofingBasketMaker.maker.skill/140) end; q=math.min(2.5,q); ProofingBasketMaker.productStock[m.productType]=(ProofingBasketMaker.productStock[m.productType] or 0)+m.quantity; ProofingBasketMaker.totalProducts=ProofingBasketMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ProofingBasketMaker.maker then ProofingBasketMaker.maker.itemsMade=ProofingBasketMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ProofingBasketMaker.maker.skill=math.min(100,ProofingBasketMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Košara izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"proofingbasket.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ProofingBasketMaker.update(dt) if not _G.state then return end; ProofingBasketMaker.dayTimer=ProofingBasketMaker.dayTimer+dt; if ProofingBasketMaker.dayTimer>=30 then ProofingBasketMaker.dayTimer=0; for i=#ProofingBasketMaker.activeMaking,1,-1 do local m=ProofingBasketMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ProofingBasketMaker.completeMaking(m); table.remove(ProofingBasketMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ProofingBasketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ProofingBasketMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ProofingBasketMaker.getStats() return {ironStock=ProofingBasketMaker.ironStock,bronzeStock=ProofingBasketMaker.bronzeStock,woodStock=ProofingBasketMaker.woodStock,leatherStock=ProofingBasketMaker.leatherStock,silverStock=ProofingBasketMaker.silverStock,goldStock=ProofingBasketMaker.goldStock,jewelStock=ProofingBasketMaker.jewelStock,pearlStock=ProofingBasketMaker.pearlStock,productStock=ProofingBasketMaker.productStock,numBuildings=#ProofingBasketMaker.buildings,hasMaker=ProofingBasketMaker.maker~=nil,makerName=ProofingBasketMaker.maker and ProofingBasketMaker.maker.name or "—",makerSkill=ProofingBasketMaker.maker and ProofingBasketMaker.maker.skill or 0,activeMaking=#ProofingBasketMaker.activeMaking,totalProducts=ProofingBasketMaker.totalProducts} end
return ProofingBasketMaker
